-define(LAW_NO_LONGER_RUN_OF_THE_NEWEST_PAIRS_WOULD_FIT,
    <<"cake.laws.prompt_drivers::|no longer run of the newest pairs would fit|">>
).

%% |no longer run of the newest pairs would fit| — laws/prompt_drivers.lawspec:804
%% On a budget that is not zero, what fit_answer_pairs/2 returns is the
%%     longest run of the newest pairs that fits: it is the newest pairs, it
%%     costs no more than the budget, and either every pair survived or the
%%     newest evicted pair would take the survivors over the budget. So a pair
%%     is never evicted while it and everything newer still fit.
%% for all (seeds :: List (cake.laws.prompt_drivers::type::PairSeed)) (budget :: BigUInt) => isLongestFit (fitAnswerPairs (pairsOf seeds) budget) (pairsOf seeds) budget = true end for all
law_no_longer_run_of_the_newest_pairs_would_fit(Schema, Symbols, [Seeds, Budget]) ->
    lawspec_beam_runtime:assert_equal(
        lawspec_definitions:is_longest_fit(
            Schema,
            Symbols,
            lawspec_definitions:fit_answer_pairs(
                Schema,
                Symbols,
                lawspec_definitions:pairs_of(Schema, Symbols, Seeds),
                Budget
            ),
            lawspec_definitions:pairs_of(Schema, Symbols, Seeds),
            Budget
        ),
        true,
        ?LAW_NO_LONGER_RUN_OF_THE_NEWEST_PAIRS_WOULD_FIT
    ).

