                                    {<<"BigUInt">>, []},
                                    Schema,
                                    Symbols,
                                    [
                                        {
                                            <<">=">>,
                                            lawspec_beam_scalar:divide(
                                                lawspec_beam_scalar:negate((0 - 1)),
                                                1,
                                                <<"Integer">>,
                                                <<"Integer">>
                                            )
                                        },
                                        {
                                            <<"<=">>,
                                            lawspec_beam_scalar:divide(
                                                lawspec_beam_scalar:negate((0 - 12)),
                                                1,
                                                <<"Integer">>,
                                                <<"Integer">>
                                            )
                                        },
                                        {<<">=">>, 1},
                                        {<<"<=">>, 12}
                                    ],
                                    [0, 1, 340282366920938463463374607431768211456],
                                    none
                                ),
                                fun(Budget) -> ((Budget >= 1) andalso (Budget =< 12)) end
                            ),
                            fun(Budget) ->
                                'Elixir.LawSpec.Beam.StreamData':exactly([Seeds, Budget])
                            end
                        )
                    end
                )
            ),
            fun(Values) ->
                law_no_longer_run_of_the_newest_pairs_would_fit(Schema, Symbols, Values)
            end
        ),
        [{numtests, 100}, {constraint_tries, 10000}, {max_shrinks, 1000}]
    ).

-define(LAW_A_BUDGET_OF_ZERO_KEEPS_NO_PAIR,
    <<"cake.laws.prompt_drivers::|a budget of zero keeps no pair|">>
).

%% |a budget of zero keeps no pair| — laws/prompt_drivers.lawspec:827
%% fit_answer_pairs/2 with a budget of zero returns no pairs, whatever it
%%     is given. That includes pairs that cost nothing: a zero budget switches
%%     the accumulated answers off, it does not admit the ones that are free.
%% for all (seeds :: List (cake.laws.prompt_drivers::type::PairSeed)) => Length(fitAnswerPairs (pairsOf seeds) 0) = 0 end for all
law_a_budget_of_zero_keeps_no_pair(Schema, Symbols, [Seeds]) ->
    lawspec_beam_runtime:assert_equal(
        lawspec_beam_runtime:helper(
            <<"length">>,
            [
                lawspec_definitions:fit_answer_pairs(
                    Schema,
                    Symbols,
                    lawspec_definitions:pairs_of(Schema, Symbols, Seeds),
                    0
                )
            ],
            [<<"List cake.laws.prompt_drivers::type::AnswerPair">>],
            64
        ),
        0,
        ?LAW_A_BUDGET_OF_ZERO_KEEPS_NO_PAIR
    ).

