-define(LAW_WITH_NO_SURVIVING_PAIR_THE_PROMPT_IS_BUILD_4_S,
    <<"cake.laws.prompt_drivers::|with no surviving pair, the prompt is build/4's|">>
).

%% |with no surviving pair, the prompt is build/4's| — laws/prompt_drivers.lawspec:847
%% build_with_prior_answers/5 returns exactly what build/4 returns for the
%%     same chunks, question and history whenever no pair survives the budget:
%%     when there are no pairs, when the budget is zero, and when not even the
%%     newest pair fits. No heading for the answers is left behind.
%% for all (contexts :: List (Text)) (question :: Text) (seeds :: List (cake.laws.prompt_drivers::type::PairSeed)) (history :: List (Text)) (budget :: BigUInt) => promptWithPriorAnswers contexts question (List::Nil()) history budget = plainPrompt contexts question history and promptWithPriorAnswers contexts question (pairsOf seeds) history 0 = plainPrompt contexts question history and (Not((Length(keptPairs (pairsOf seeds) budget) == 0)) Or (promptWithPriorAnswers contexts question (pairsOf seeds) history budget == plainPrompt contexts question history)) = true end for all
law_with_no_surviving_pair_the_prompt_is_build_4_s(
    Schema,
    Symbols,
    [Contexts, Question, Seeds, History, Budget]
) ->
    ((lawspec_beam_runtime:assert_equal(
        lawspec_definitions:prompt_with_prior_answers(
            Schema,
            Symbols,
            Contexts,
            Question,
            [],
            History,
            Budget
        ),
        lawspec_definitions:plain_prompt(Schema, Symbols, Contexts, Question, History),
        ?LAW_WITH_NO_SURVIVING_PAIR_THE_PROMPT_IS_BUILD_4_S
    ) andalso
        lawspec_beam_runtime:assert_equal(
            lawspec_definitions:prompt_with_prior_answers(
                Schema,
                Symbols,
                Contexts,
                Question,
                lawspec_definitions:pairs_of(Schema, Symbols, Seeds),
                History,
                0
            ),
            lawspec_definitions:plain_prompt(Schema, Symbols, Contexts, Question, History),
            ?LAW_WITH_NO_SURVIVING_PAIR_THE_PROMPT_IS_BUILD_4_S
        )) andalso
        lawspec_beam_runtime:assert_equal(
            ((not (lawspec_beam_runtime:helper(
                <<"length">>,
                [
                    lawspec_definitions:kept_pairs(
                        Schema,
                        Symbols,
                        lawspec_definitions:pairs_of(Schema, Symbols, Seeds),
                        Budget
                    )
                ],
                [<<"List cake.laws.prompt_drivers::type::AnswerPair">>],
                64
            ) =:=
                0)) orelse
                lawspec_beam_scalar:equal(
                    lawspec_definitions:prompt_with_prior_answers(
                        Schema,
                        Symbols,
                        Contexts,
                        Question,
                        lawspec_definitions:pairs_of(Schema, Symbols, Seeds),
                        History,
                        Budget
                    ),
                    lawspec_definitions:plain_prompt(Schema, Symbols, Contexts, Question, History)
                )),
            true,
            ?LAW_WITH_NO_SURVIVING_PAIR_THE_PROMPT_IS_BUILD_4_S
        )).

