    {Schema, Symbols} = lawspec_data:context(),
    Contexts = [<<"Flow is laminar">>],
    Question = <<"final?">>,
    Seeds = make_cons_4(
        [
            make_pair_seed(
                [<<"first sub-question asked">>, <<"the very first intermediate answer">>, 0],
                Schema
            ),
            make_cons_4(
                [make_pair_seed([<<"last sub-question">>, <<"newest answer">>, 0], Schema), []],
                Schema
            )
        ],
        Schema
    ),
    History = [],
    Budget = 9,
    lawspec_beam_runtime:require(
        law_the_prompt_folds_in_the_surviving_pairs_and_no(
            Schema,
            Symbols,
            [Contexts, Question, Seeds, History, Budget]
        ),
        ?LAW_THE_PROMPT_FOLDS_IN_THE_SURVIVING_PAIRS_AND_NO
    ),
    lawspec_beam_runtime:assert_equal(
        lawspec_beam_runtime:helper(
            <<"textContains">>,
            [
                lawspec_definitions:system_of(
                    Schema,
                    Symbols,
                    lawspec_definitions:prompt_with_prior_answers(
                        Schema,
                        Symbols,
                        Contexts,
                        Question,
                        lawspec_definitions:pairs_of(Schema, Symbols, Seeds),
                        History,
                        Budget
                    )
                ),
                <<"newest answer">>
            ],
            [<<"Text">>, <<"Text">>],
            64
        ),
        true,
        <<"|the prompt folds in the surviving pairs and no others| example |the newest pair is folded in and the evicted one is not| — laws/prompt_drivers.lawspec:931"/utf8>>
    ),
    lawspec_beam_runtime:assert_equal(
        lawspec_beam_runtime:helper(
            <<"textContains">>,
            [
                lawspec_definitions:system_of(
                    Schema,
                    Symbols,
                    lawspec_definitions:prompt_with_prior_answers(
                        Schema,
                        Symbols,
                        Contexts,
                        Question,
                        lawspec_definitions:pairs_of(Schema, Symbols, Seeds),
                        History,
                        Budget
                    )
                ),
                <<"the very first intermediate answer">>
            ],
            [<<"Text">>, <<"Text">>],
            64
        ),
        false,
        <<"|the prompt folds in the surviving pairs and no others| example |the newest pair is folded in and the evicted one is not| — laws/prompt_drivers.lawspec:933"/utf8>>
