-define(LAW_THE_FINAL_ANSWER_MARKER_WINS_OVER_A_FOLLOW_UP,
    <<"cake.laws.prompt_drivers::|the final-answer marker wins over a follow-up|">>
).

%% |the final-answer marker wins over a follow-up| — laws/prompt_drivers.lawspec:1097
%% A reply that has the final-answer marker anywhere is the final answer,
%%     whatever surrounds the marker: follow-up markers before it, after it, or
%%     on both sides. A model that answers in one breath has answered.
%% for all (before :: Text) (between :: Text) (after :: Text) => isFinal (parseSelfAsk (Append(Append(before, "So the final answer is:"), after))) = true and isFinal (parseSelfAsk (Append(Append(Append(Append(before, "Follow up:"), between), "So the final answer is:"), after))) = true and isFinal (parseSelfAsk (Append(Append(Append(Append(before, "So the final answer is:"), between), "Follow up:"), after))) = true end for all
law_the_final_answer_marker_wins_over_a_follow_up(Schema, Symbols, [Before, Between, After]) ->
    ((lawspec_beam_runtime:assert_equal(
        lawspec_definitions:is_final(
            Schema,
            Symbols,
            lawspec_definitions:parse_self_ask(
                Schema,
                Symbols,
                lawspec_beam_runtime:helper(
                    <<"append">>,
                    [
                        lawspec_beam_runtime:helper(
                            <<"append">>,
                            [Before, <<"So the final answer is:">>],
                            [<<"Text">>, <<"Text">>],
                            64
                        ),
                        After
                    ],
                    [<<"Text">>, <<"Text">>],
                    64
                )
            )
        ),
        true,
        ?LAW_THE_FINAL_ANSWER_MARKER_WINS_OVER_A_FOLLOW_UP
    ) andalso
        lawspec_beam_runtime:assert_equal(
            lawspec_definitions:is_final(
                Schema,
                Symbols,
                lawspec_definitions:parse_self_ask(
                    Schema,
                    Symbols,
                    lawspec_beam_runtime:helper(
                        <<"append">>,
                        [
                            lawspec_beam_runtime:helper(
                                <<"append">>,
                                [
                                    lawspec_beam_runtime:helper(
                                        <<"append">>,
                                        [
                                            lawspec_beam_runtime:helper(
                                                <<"append">>,
                                                [Before, <<"Follow up:">>],
                                                [<<"Text">>, <<"Text">>],
                                                64
                                            ),
                                            Between
                                        ],
                                        [<<"Text">>, <<"Text">>],
                                        64
                                    ),
                                    <<"So the final answer is:">>
                                ],
                                [<<"Text">>, <<"Text">>],
                                64
                            ),
                            After
                        ],
                        [<<"Text">>, <<"Text">>],
                        64
                    )
                )
            ),
            true,
            ?LAW_THE_FINAL_ANSWER_MARKER_WINS_OVER_A_FOLLOW_UP
        )) andalso
        lawspec_beam_runtime:assert_equal(
            lawspec_definitions:is_final(
                Schema,
                Symbols,
                lawspec_definitions:parse_self_ask(
                    Schema,
                    Symbols,
                    lawspec_beam_runtime:helper(
                        <<"append">>,
                        [
                            lawspec_beam_runtime:helper(
                                <<"append">>,
                                [
                                    lawspec_beam_runtime:helper(
                                        <<"append">>,
                                        [
                                            lawspec_beam_runtime:helper(
                                                <<"append">>,
                                                [Before, <<"So the final answer is:">>],
                                                [<<"Text">>, <<"Text">>],
                                                64
                                            ),
                                            Between
                                        ],
                                        [<<"Text">>, <<"Text">>],
                                        64
                                    ),
                                    <<"Follow up:">>
                                ],
                                [<<"Text">>, <<"Text">>],
                                64
                            ),
                            After
                        ],
                        [<<"Text">>, <<"Text">>],
                        64
                    )
                )
            ),
            true,
            ?LAW_THE_FINAL_ANSWER_MARKER_WINS_OVER_A_FOLLOW_UP
        )).

