-define(LAW_THE_LAST_FOLLOW_UP_WINS_WHEN_THERE_ARE_SEVERAL,
    <<"cake.laws.prompt_drivers::|the last follow-up wins when there are several|">>
).

%% |the last follow-up wins when there are several| — laws/prompt_drivers.lawspec:1122
%% In a reply with no final-answer marker and two or more follow-up
%%     markers, the last follow-up marker decides: the reply is that marker's
%%     question, whatever the earlier follow-ups asked, since the model was
%%     echoing follow-ups already resolved. If the last marker is trailed by
%%     nothing, the whole reply is the final answer, and no earlier follow-up is
%%     asked again.
%% for all (lead :: cake.laws.prompt_drivers::type::Margin) (earlier :: cake.laws.prompt_drivers::type::Marked) (between :: List (cake.laws.prompt_drivers::type::ReplyLine)) (last :: cake.laws.prompt_drivers::type::Marked) (after :: List (cake.laws.prompt_drivers::type::ReplyLine)) (trail :: cake.laws.prompt_drivers::type::Margin) => parseSelfAsk (replyText lead (severalAsks earlier between last after) trail) = decidedBy last (severalAsks earlier between last after) end for all
law_the_last_follow_up_wins_when_there_are_several(
    Schema,
    Symbols,
    [Lead, Earlier, Between, Last, After, Trail]
) ->
    lawspec_beam_runtime:assert_equal(
        lawspec_definitions:parse_self_ask(
            Schema,
            Symbols,
            lawspec_definitions:reply_text(
                Schema,
                Symbols,
                Lead,
                lawspec_definitions:several_asks(Schema, Symbols, Earlier, Between, Last, After),
                Trail
            )
        ),
        lawspec_definitions:decided_by(
            Schema,
            Symbols,
            Last,
            lawspec_definitions:several_asks(Schema, Symbols, Earlier, Between, Last, After)
        ),
        ?LAW_THE_LAST_FOLLOW_UP_WINS_WHEN_THERE_ARE_SEVERAL
    ).

