-define(LAW_EVERY_REPLY_IS_A_FINAL_ANSWER_OR_A_FOLLOW_UP,
    <<"cake.laws.prompt_drivers::|every reply is a final answer or a follow-up, taken from the reply|">>
).

%% |every reply is a final answer or a follow-up, taken from the reply| — laws/prompt_drivers.lawspec:1162
%% parse_self_ask_response/1 classifies any text at all, with or without
%%     markers, and never invents text. A final answer is part of the reply. A
%%     follow-up is part of a reply that has the follow-up marker and no
%%     final-answer marker, and it is a single line that is not empty.
%% for all (before :: Text) (between :: Text) (after :: Text) => soundStep before (parseSelfAsk before) = true and soundStep (Append(Append(before, "Follow up:"), after)) (parseSelfAsk (Append(Append(before, "Follow up:"), after))) = true and soundStep (Append(Append(Append(Append(before, "Follow up:"), between), "Follow up:"), after)) (parseSelfAsk (Append(Append(Append(Append(before, "Follow up:"), between), "Follow up:"), after))) = true and soundStep (Append(Append(before, "So the final answer is:"), after)) (parseSelfAsk (Append(Append(before, "So the final answer is:"), after))) = true and soundStep (Append(Append(Append(Append(before, "Follow up:"), between), "So the final answer is:"), after)) (parseSelfAsk (Append(Append(Append(Append(before, "Follow up:"), between), "So the final answer is:"), after))) = true end for all
law_every_reply_is_a_final_answer_or_a_follow_up(Schema, Symbols, [Before, Between, After]) ->
    ((((lawspec_beam_runtime:assert_equal(
        lawspec_definitions:sound_step(
            Schema,
            Symbols,
            Before,
            lawspec_definitions:parse_self_ask(Schema, Symbols, Before)
        ),
        true,
        ?LAW_EVERY_REPLY_IS_A_FINAL_ANSWER_OR_A_FOLLOW_UP
    ) andalso
        lawspec_beam_runtime:assert_equal(
            lawspec_definitions:sound_step(
                Schema,
                Symbols,
                lawspec_beam_runtime:helper(
                    <<"append">>,
                    [
                        lawspec_beam_runtime:helper(
