law_every_reply_is_a_final_answer_or_a_follow_up_plan() ->
    [
        {
            finite,
            {
                branches,
                [
                    {
                        {values, [fun(_Symbols) -> <<>> end]},
                        {
                            branches,
                            [
                                {
                                    {values, [fun(_Symbols) -> <<>> end]},
                                    {
