%% |every reply is a final answer or a follow-up, taken from the reply| property — laws/prompt_drivers.lawspec:1162
law_every_reply_is_a_final_answer_or_a_follow_up__property() ->
    {Schema, Symbols} = lawspec_data:context(),
    lawspec_beam_search:replay(
        ?LAW_EVERY_REPLY_IS_A_FINAL_ANSWER_OR_A_FOLLOW_UP,
        [<<"(text)">>, <<"(text)">>, <<"(text)">>],
        fun([Before, Between, After]) ->
            lawspec_beam_runtime:require(
                law_every_reply_is_a_final_answer_or_a_follow_up(
                    Schema,
                    Symbols,
                    [Before, Between, After]
                ),
                ?LAW_EVERY_REPLY_IS_A_FINAL_ANSWER_OR_A_FOLLOW_UP
            )
        end
    ),
    'Elixir.LawSpec.Beam.StreamData':check(
        ?LAW_EVERY_REPLY_IS_A_FINAL_ANSWER_OR_A_FOLLOW_UP,
        'Elixir.LawSpec.Beam.StreamData':forall(
            'Elixir.LawSpec.Beam.StreamData':complete(
                'Elixir.LawSpec.Beam.StreamData':bind(
                    'Elixir.LawSpec.Beam.StreamData':generator(
                        {<<"Text">>, []},
                        Schema,
                        Symbols,
                        [],
                        [
                            <<>>,
                            <<" ">>,
                            <<"Hello, World!">>,
                            <<"λ日本語😀"/utf8>>,
                            <<"a\n\t\"\\$\x{0}z">>,
                            <<"é"/utf8>>,
                            <<>>,
                            <<"\x{0}aλ😀\x{10ffff}"/utf8>>
                        ],
                        none
                    ),
                    fun(Before) ->
                        'Elixir.LawSpec.Beam.StreamData':bind(
                            'Elixir.LawSpec.Beam.StreamData':generator(
                                {<<"Text">>, []},
                                Schema,
                                Symbols,
                                [],
                                [
                                    <<>>,
                                    <<" ">>,
                                    <<"Hello, World!">>,
                                    <<"λ日本語😀"/utf8>>,
                                    <<"a\n\t\"\\$\x{0}z">>,
                                    <<"é"/utf8>>,
                                    <<>>,
                                    <<"\x{0}aλ😀\x{10ffff}"/utf8>>
                                ],
                                none
                            ),
                            fun(Between) ->
                                'Elixir.LawSpec.Beam.StreamData':bind(
                                    'Elixir.LawSpec.Beam.StreamData':generator(
                                        {<<"Text">>, []},
                                        Schema,
                                        Symbols,
                                        [],
                                        [
                                            <<>>,
                                            <<" ">>,
                                            <<"Hello, World!">>,
                                            <<"λ日本語😀"/utf8>>,
                                            <<"a\n\t\"\\$\x{0}z">>,
                                            <<"é"/utf8>>,
                                            <<>>,
                                            <<"\x{0}aλ😀\x{10ffff}"/utf8>>
                                        ],
                                        none
                                    ),
                                    fun(After) ->
                                        'Elixir.LawSpec.Beam.StreamData':exactly(
                                            [Before, Between, After]
                                        )
                                    end
                                )
                            end
                        )
                    end
                )
            ),
            fun(Values) ->
                lawspec_beam_search:guard(
                    ?LAW_EVERY_REPLY_IS_A_FINAL_ANSWER_OR_A_FOLLOW_UP,
                    [<<"(text)">>, <<"(text)">>, <<"(text)">>],
                    Values,
                    fun() ->
                        law_every_reply_is_a_final_answer_or_a_follow_up(Schema, Symbols, Values)
                    end
                )
            end
        ),
        [{numtests, 100}, {constraint_tries, 10000}, {max_shrinks, 1000}]
    ).

-define(LAW_THE_IRCOT_PROMPT_FOLDS_IN_THE_NEWEST_STEPS_THAT,
    <<"cake.laws.prompt_drivers::|the IRCoT prompt folds in the newest steps that fit the budget|">>
).

%% |the IRCoT prompt folds in the newest steps that fit the budget| — laws/prompt_drivers.lawspec:1187
%% ircot_prompt/3 returns two messages: a system message, then the
%%     question as a user message, verbatim. The system message starts with the
%%     IRCoT instructions and holds the steps that survive the budget, each with
%%     its reasoning and every context retrieved for it, labelled Step 1 to
%%     Step K, oldest first. The survivors are the longest run of the newest
%%     steps that costs no more than the budget, a step costing the token
%%     estimate of its reasoning plus that of each of its contexts, so a step's
%%     reasoning and its contexts are kept or evicted together. An evicted step
%%     leaves no trace: the prompt is the one the survivors alone would give,
%%     labelled from 1 again.
%% for all (question :: Text) (seeds :: List (cake.laws.prompt_drivers::type::StepSeed)) (budget :: BigUInt) => ircotPrompt question (stepsOf seeds) budget = ircotPrompt question (keptSteps (stepsOf seeds) budget) budget and leadsWithSystem (ircotPrompt question (stepsOf seeds) budget) = true and afterSystem (ircotPrompt question (stepsOf seeds) budget) = List::Cons(let _lawspecRecordField0 = cake.laws.prompt_context::type::Role::User() in let _lawspecRecordField1 = question in cake.laws.prompt_context::type::Message::Message(_lawspecRecordField0, _lawspecRecordField1), List::Nil()) and (systemOf (ircotPrompt question (stepsOf seeds) budget) starts with ircotSystemMessage unitValue) = true and holdsExactly (keptSteps (stepsOf seeds) budget) (foldedAfter (ircotSystemMessage unitValue) (systemOf (ircotPrompt question (stepsOf seeds) budget))) = true end for all
law_the_ircot_prompt_folds_in_the_newest_steps_that(Schema, Symbols, [Question, Seeds, Budget]) ->
    ((((lawspec_beam_runtime:assert_equal(
        lawspec_definitions:ircot_prompt(
            Schema,
            Symbols,
            Question,
            lawspec_definitions:steps_of(Schema, Symbols, Seeds),
            Budget
        ),
        lawspec_definitions:ircot_prompt(
            Schema,
            Symbols,
            Question,
            lawspec_definitions:kept_steps(
                Schema,
                Symbols,
                lawspec_definitions:steps_of(Schema, Symbols, Seeds),
                Budget
            ),
            Budget
        ),
        ?LAW_THE_IRCOT_PROMPT_FOLDS_IN_THE_NEWEST_STEPS_THAT
    ) andalso
        lawspec_beam_runtime:assert_equal(
            lawspec_definitions:leads_with_system(
                Schema,
                Symbols,
                lawspec_definitions:ircot_prompt(
                    Schema,
                    Symbols,
                    Question,
                    lawspec_definitions:steps_of(Schema, Symbols, Seeds),
                    Budget
                )
            ),
            true,
            ?LAW_THE_IRCOT_PROMPT_FOLDS_IN_THE_NEWEST_STEPS_THAT
        )) andalso
        lawspec_beam_runtime:assert_equal(
            lawspec_definitions:after_system(
                Schema,
                Symbols,
                lawspec_definitions:ircot_prompt(
                    Schema,
                    Symbols,
                    Question,
                    lawspec_definitions:steps_of(Schema, Symbols, Seeds),
                    Budget
                )
            ),
            make_cons_2(
                [
                    lawspec_beam_runtime:bind(
                        make_user([], Schema),
                        fun(RecordField) ->
                            lawspec_beam_runtime:bind(
                                Question,
                                fun(RecordField_2) ->
                                    make_message([RecordField, RecordField_2], Schema)
                                end
                            )
                        end
                    ),
                    []
                ],
                Schema
            ),
            ?LAW_THE_IRCOT_PROMPT_FOLDS_IN_THE_NEWEST_STEPS_THAT
        )) andalso
        lawspec_beam_runtime:assert_equal(
            lawspec_beam_runtime:helper(
                <<"startsWith">>,
                [
                    lawspec_definitions:system_of(
                        Schema,
                        Symbols,
                        lawspec_definitions:ircot_prompt(
                            Schema,
                            Symbols,
                            Question,
                            lawspec_definitions:steps_of(Schema, Symbols, Seeds),
                            Budget
                        )
                    ),
                    lawspec_definitions:ircot_system_message(Schema, Symbols, ls_unit)
                ],
                [<<"Text">>, <<"Text">>],
                64
            ),
            true,
            ?LAW_THE_IRCOT_PROMPT_FOLDS_IN_THE_NEWEST_STEPS_THAT
        )) andalso
        lawspec_beam_runtime:assert_equal(
            lawspec_definitions:holds_exactly(
                Schema,
                Symbols,
                lawspec_definitions:kept_steps(
                    Schema,
                    Symbols,
                    lawspec_definitions:steps_of(Schema, Symbols, Seeds),
                    Budget
                ),
                lawspec_definitions:folded_after(
                    Schema,
                    Symbols,
                    lawspec_definitions:ircot_system_message(Schema, Symbols, ls_unit),
                    lawspec_definitions:system_of(
                        Schema,
                        Symbols,
                        lawspec_definitions:ircot_prompt(
                            Schema,
                            Symbols,
                            Question,
                            lawspec_definitions:steps_of(Schema, Symbols, Seeds),
                            Budget
                        )
                    )
                )
            ),
            true,
            ?LAW_THE_IRCOT_PROMPT_FOLDS_IN_THE_NEWEST_STEPS_THAT
        )).

