-define(LAW_WITH_NO_SURVIVING_STEP_THE_IRCOT_PROMPT_IS_ITS,
    <<"cake.laws.prompt_drivers::|with no surviving step, the IRCoT prompt is its instructions alone|">>
).

%% |with no surviving step, the IRCoT prompt is its instructions alone| — laws/prompt_drivers.lawspec:1263
%% ircot_prompt/3 returns exactly the IRCoT instructions and the question
%%     whenever no step survives the budget: when there are no steps, when the
%%     budget is zero, and when not even the newest step fits. A zero budget
%%     keeps nothing, not even a step that costs nothing, and no heading for
%%     the steps is left behind.
%% for all (question :: Text) (seeds :: List (cake.laws.prompt_drivers::type::StepSeed)) (budget :: BigUInt) => ircotPrompt question (List::Nil()) budget = List::Cons(let _lawspecRecordField0 = cake.laws.prompt_context::type::Role::System() in let _lawspecRecordField1 = ircotSystemMessage unitValue in cake.laws.prompt_context::type::Message::Message(_lawspecRecordField0, _lawspecRecordField1), List::Cons(let _lawspecRecordField0 = cake.laws.prompt_context::type::Role::User() in let _lawspecRecordField1 = question in cake.laws.prompt_context::type::Message::Message(_lawspecRecordField0, _lawspecRecordField1), List::Nil())) and ircotPrompt question (stepsOf seeds) 0 = ircotPrompt question (List::Nil()) 0 and (Not((Length(keptSteps (stepsOf seeds) budget) == 0)) Or (ircotPrompt question (stepsOf seeds) budget == ircotPrompt question (List::Nil()) budget)) = true end for all
law_with_no_surviving_step_the_ircot_prompt_is_its(Schema, Symbols, [Question, Seeds, Budget]) ->
    ((lawspec_beam_runtime:assert_equal(
        lawspec_definitions:ircot_prompt(Schema, Symbols, Question, [], Budget),
        make_cons_2(
            [
                lawspec_beam_runtime:bind(
                    make_system([], Schema),
                    fun(RecordField) ->
                        lawspec_beam_runtime:bind(
                            lawspec_definitions:ircot_system_message(Schema, Symbols, ls_unit),
                            fun(RecordField_2) ->
                                make_message([RecordField, RecordField_2], Schema)
                            end
                        )
                    end
                ),
                make_cons_2(
                    [
                        lawspec_beam_runtime:bind(
                            make_user([], Schema),
                            fun(RecordField) ->
                                lawspec_beam_runtime:bind(
                                    Question,
                                    fun(RecordField_2) ->
                                        make_message([RecordField, RecordField_2], Schema)
                                    end
                                )
                            end
                        ),
                        []
                    ],
                    Schema
                )
            ],
            Schema
        ),
        ?LAW_WITH_NO_SURVIVING_STEP_THE_IRCOT_PROMPT_IS_ITS
    ) andalso
        lawspec_beam_runtime:assert_equal(
            lawspec_definitions:ircot_prompt(
                Schema,
                Symbols,
                Question,
                lawspec_definitions:steps_of(Schema, Symbols, Seeds),
                0
            ),
            lawspec_definitions:ircot_prompt(Schema, Symbols, Question, [], 0),
            ?LAW_WITH_NO_SURVIVING_STEP_THE_IRCOT_PROMPT_IS_ITS
        )) andalso
        lawspec_beam_runtime:assert_equal(
            ((not (lawspec_beam_runtime:helper(
                <<"length">>,
                [
                    lawspec_definitions:kept_steps(
                        Schema,
                        Symbols,
                        lawspec_definitions:steps_of(Schema, Symbols, Seeds),
                        Budget
                    )
                ],
                [<<"List cake.laws.prompt_drivers::type::ReasoningStep">>],
                64
            ) =:=
                0)) orelse
                lawspec_beam_scalar:equal(
                    lawspec_definitions:ircot_prompt(
                        Schema,
                        Symbols,
                        Question,
                        lawspec_definitions:steps_of(Schema, Symbols, Seeds),
                        Budget
                    ),
                    lawspec_definitions:ircot_prompt(Schema, Symbols, Question, [], Budget)
                )),
            true,
            ?LAW_WITH_NO_SURVIVING_STEP_THE_IRCOT_PROMPT_IS_ITS
        )).

law_with_no_surviving_step_the_ircot_prompt_is_its_plan() ->
    [
        {
            fixed,
            [
