-define(LAW_A_NULL_OR_BLANK_RETRIEVAL_QUERY_MEANS_DONE_ANY,
    <<"cake.laws.prompt_drivers::|a null or blank retrieval query means done, any other continues|">>
).

%% |a null or blank retrieval query means done, any other continues| — laws/prompt_drivers.lawspec:1336
%% parse_ircot_response/1 classifies a step by its retrieval query. With no
%%     query, or a query that is only whitespace, the chain is done and the
%%     reasoning is the final answer. With any other query the chain continues
%%     with that query. The reasoning and the query both come back trimmed.
%% for all (reasoning :: cake.laws.prompt_drivers::type::Field) (query :: Maybe (cake.laws.prompt_drivers::type::Field)) => parseIrcot (fieldText reasoning) (queryText query) = verdictOf reasoning query end for all
law_a_null_or_blank_retrieval_query_means_done_any(Schema, Symbols, [Reasoning, Query]) ->
    lawspec_beam_runtime:assert_equal(
        lawspec_definitions:parse_ircot(
            Schema,
            Symbols,
            lawspec_definitions:field_text(Schema, Symbols, Reasoning),
            lawspec_definitions:query_text(Schema, Symbols, Query)
        ),
        lawspec_definitions:verdict_of(Schema, Symbols, Reasoning, Query),
        ?LAW_A_NULL_OR_BLANK_RETRIEVAL_QUERY_MEANS_DONE_ANY
    ).

