-define(LAW_EVERY_IRCOT_STEP_IS_DONE_OR_CONTINUES_WITH_A,
    <<"cake.laws.prompt_drivers::|every IRCoT step is done or continues with a query it was given|">>
).

%% |every IRCoT step is done or continues with a query it was given| — laws/prompt_drivers.lawspec:1396
%% parse_ircot_response/1 classifies any reasoning text with any retrieval
%%     query or none, and never invents text. The reasoning it returns is part
%%     of the reasoning it was given. A step with no query is always done. A
%%     step that continues was given a query, and the query it continues with
%%     is part of that one and is not empty.
%% for all (reasoning :: Text) (query :: Maybe (Text)) => soundVerdict reasoning query (parseIrcot reasoning query) = true and isDone (parseIrcot reasoning (Maybe::Absent())) = true end for all
law_every_ircot_step_is_done_or_continues_with_a(Schema, Symbols, [Reasoning, Query]) ->
    (lawspec_beam_runtime:assert_equal(
        lawspec_definitions:sound_verdict(
            Schema,
            Symbols,
            Reasoning,
            Query,
            lawspec_definitions:parse_ircot(Schema, Symbols, Reasoning, Query)
        ),
        true,
        ?LAW_EVERY_IRCOT_STEP_IS_DONE_OR_CONTINUES_WITH_A
    ) andalso
        lawspec_beam_runtime:assert_equal(
            lawspec_definitions:is_done(
                Schema,
                Symbols,
                lawspec_definitions:parse_ircot(Schema, Symbols, Reasoning, make_absent([], Schema))
            ),
            true,
            ?LAW_EVERY_IRCOT_STEP_IS_DONE_OR_CONTINUES_WITH_A
        )).

